// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title HashplayWithdraw
 * @notice A replacement contract with corrected HBAR withdrawal using Hedera precompile.
 * This contract mimics HashplayGame but fixes the withdrawHBAR function
 * by using a low-level call instead of payable().transfer().
 * 
 * On Hedera, native transfers via the Hedera precompile at 0x16c work correctly.
 * See: https://docs.hedera.com/hedera/core-concepts/smart-contracts/system-smart-contracts
 */
contract HashplayWithdraw {
    address public owner;

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    /**
     * @notice Withdraw HBAR to the owner using a low-level call.
     * Hedera blocks payable().transfer() in contracts, but a 
     * low-level .call{value: amount}("") to an EOA works correctly.
     */
    function withdrawAllHBAR() external onlyOwner {
        uint256 bal = address(this).balance;
        require(bal > 0, "No HBAR to withdraw");
        (bool success, ) = payable(owner).call{value: bal}("");
        require(success, "Transfer failed");
    }

    receive() external payable {}
    fallback() external payable {}
}

contracts/HBARDrainer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @notice Helper to drain HBAR from old HashplayGame contracts.
 * On Hedera, payable(addr).transfer() between contracts is blocked.
 * Instead, we use the Hedera IExchangeRate precompile at 0x168
 * (cryptoTransfer) or simply a low-level call with value.
 * 
 * The trick: The calling contract initiates a .call{value: amount}("") 
 * which works for contract->EOA but not contract->contract on Hedera.
 * 
 * REAL SOLUTION: Use the actual Hedera CryptoTransfer precompile (address 0x16c).
 * Its IHederaTokenService selector for transferHBAR is different.
 * 
 * Alternatively, use sendTo which works on Hedera via low-level call:
 */
contract HBARDrainer {
    address payable public treasury;
    
    constructor(address payable _treasury) {
        treasury = _treasury;
    }
    
    // Called by the old contract via its withdrawHBAR after sending to this address  
    receive() external payable {
        treasury.call{value: address(this).balance}("");
    }
    
    fallback() external payable {
        treasury.call{value: address(this).balance}("");
    }
}

